"""Brute-force DP vs. the proposed closed-form formula, over all count tuples."""
from functools import lru_cache
from itertools import combinations

PRICES = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}


@lru_cache(maxsize=None)
def dp(counts):
    counts = list(counts)
    d = sum(1 for c in counts if c > 0)
    if d == 0:
        return 0
    best = float("inf")
    pos = [i for i, c in enumerate(counts) if c > 0]
    for k in range(1, d + 1):
        for S in combinations(pos, k):
            new = list(counts)
            for i in S:
                new[i] -= 1
            new.sort(reverse=True)
            best = min(best, PRICES[k] + dp(tuple(new)))
    return best


def formula(counts):
    c = sorted(list(counts) + [0] * (5 - len(counts)), reverse=True)
    n5 = c[4]
    r = sorted((x - n5 for x in c[:4]), reverse=True)
    n4 = r[3]
    s = sorted((x - n4 for x in r[:3]), reverse=True)
    n3 = s[2]
    n2 = s[1] - n3
    n1 = s[0] - s[1]
    swaps = min(n5, n3)
    n5 -= swaps
    n3 -= swaps
    n4 += 2 * swaps
    return n1 * PRICES[1] + n2 * PRICES[2] + n3 * PRICES[3] + n4 * PRICES[4] + n5 * PRICES[5]


def all_sorted_tuples(max_total):
    def gen(remaining, max_part, depth, acc):
        if depth == 5:
            if remaining == 0:
                yield tuple(acc)
            return
        for v in range(min(max_part, remaining), -1, -1):
            yield from gen(remaining - v, v, depth + 1, acc + [v])

    for t in range(0, max_total + 1):
        yield from gen(t, t, 0, [])


def main():
    checked = 0
    for t in all_sorted_tuples(25):
        if sum(t) > 25:
            continue
        expected = dp(t)
        got = formula(t)
        checked += 1
        if expected != got:
            print(f"MISMATCH {t}: dp={expected} formula={got}")
    print(f"checked {checked} states, all match" if True else "")


if __name__ == "__main__":
    main()

